div.script:
//
document.addEventListener('DOMContentLoaded', function() {
    var container = document.getElementById('preorder_container');
    var currSymbol = container ? (container.getAttribute('data-currency-symbol') || '$') : '$';
    var combosData = {};
    try {
        combosData = JSON.parse(container ? (container.getAttribute('data-combos') || '{}') : '{}');
    } catch(e) {
        combosData = {};
    }

    var currentComboProdId = null;
    var comboModal = document.getElementById('comboModal');

    function showComboModal(prodId) {
        var meta = combosData[prodId];
        if (!meta || !meta.groups || !meta.groups.length) return;
        currentComboProdId = prodId;

        document.getElementById('comboModalTitle').textContent = 'Customize ' + meta.name;
        document.getElementById('comboModalPriceDisplay').textContent = currSymbol + ' ' + parseFloat(meta.price).toFixed(2);

        var previousChoices = [];
        var hiddenInp = document.getElementById('food_combo_data_' + prodId);
        if (hiddenInp && hiddenInp.value) {
            try {
                previousChoices = JSON.parse(hiddenInp.value);
            } catch(e) {}
        }
        var prevChoiceItemIds = previousChoices.map(function(c) { return c.combo_item_id; });

        var body = document.getElementById('comboModalBody');
        body.innerHTML = '';

        meta.groups.forEach(function(group, gIdx) {
            var groupCard = document.createElement('div');
            groupCard.className = 'mb-4 p-3 bg-light rounded-3 border';
            groupCard.style.borderColor = '#e2e8f0';

            var groupHeader = document.createElement('div');
            groupHeader.className = 'd-flex justify-content-between align-items-center mb-3 pb-2 border-bottom';
            groupHeader.innerHTML = '<h6 class="fw-bold mb-0 text-dark" style="font-size: 14.5px;">' + (gIdx + 1) + '. ' + group.name + '</h6><span class="badge bg-secondary-subtle text-secondary" style="font-size: 10px;">Choose 1</span>';
            groupCard.appendChild(groupHeader);

            var optionsGrid = document.createElement('div');
            optionsGrid.className = 'row g-2';

            group.items.forEach(function(item, iIdx) {
                var isSelected = prevChoiceItemIds.length > 0 ? prevChoiceItemIds.includes(item.id) : (iIdx === 0);
                var optCol = document.createElement('div');
                optCol.className = 'col-md-6 col-12';

                var radioId = 'combo_item_' + group.id + '_' + item.id;
                var extraPriceHtml = item.extra_price > 0 ? (' <span class="badge bg-success-subtle text-success small">+' + currSymbol + ' ' + parseFloat(item.extra_price).toFixed(2) + '</span>') : '';

                var optCard = document.createElement('label');
                optCard.className = 'card h-100 p-2 d-flex flex-row align-items-center gap-2 rounded-3 border cursor-pointer combo-opt-label w-100';
                optCard.htmlFor = radioId;
                optCard.style.cursor = 'pointer';
                optCard.style.transition = 'all 0.2s ease';
                optCard.style.borderColor = isSelected ? '#16a34a' : '#e2e8f0';
                optCard.style.backgroundColor = isSelected ? '#f0fdf4' : '#ffffff';

                var imgHtml = item.image_url ? ('<img src="' + item.image_url + '" class="rounded-2" style="width: 42px; height: 42px; object-fit: cover;" alt=""/>') : '<div class="rounded-2 bg-light d-flex align-items-center justify-content-center" style="width: 42px; height: 42px;">🍲</div>';

                optCard.innerHTML = '<input type="radio" name="combo_group_' + group.id + '" id="' + radioId + '" value="' + item.id + '" class="form-check-input mt-0 me-1" ' + (isSelected ? 'checked="checked"' : '') + ' data-prod-id="' + item.product_id + '" data-name="' + item.name.replace(/"/g, '&quot;') + '" data-group-name="' + group.name.replace(/"/g, '&quot;') + '" data-extra-price="' + (parseFloat(item.extra_price) || 0) + '" style="cursor: pointer;"/>' +
                    imgHtml +
                    '<div class="flex-grow-1" style="min-width: 0;"><div class="fw-semibold text-dark text-truncate" style="font-size: 13px;">' + item.name + '</div>' + extraPriceHtml + '</div>';

                optCol.appendChild(optCard);
                optionsGrid.appendChild(optCol);
            });

            groupCard.appendChild(optionsGrid);
            body.appendChild(groupCard);
        });

        // Add styling on click to option cards
        body.querySelectorAll('.form-check-input').forEach(function(radio) {
            radio.addEventListener('change', function() {
                var groupName = this.name;
                body.querySelectorAll('input[name="' + groupName + '"]').forEach(function(r) {
                    var lbl = r.closest('label');
                    if (lbl) {
                        if (r.checked) {
                            lbl.style.borderColor = '#16a34a';
                            lbl.style.backgroundColor = '#f0fdf4';
                        } else {
                            lbl.style.borderColor = '#e2e8f0';
                            lbl.style.backgroundColor = '#ffffff';
                        }
                    }
                });
            });
        });

        // Open modal
        if (window.bootstrap && window.bootstrap.Modal) {
            var bsModal = bootstrap.Modal.getInstance(comboModal) || new bootstrap.Modal(comboModal);
            bsModal.show();
        } else {
            comboModal.style.display = 'block';
            comboModal.classList.add('show');
        }
    }

    function hideComboModal() {
        if (window.bootstrap && window.bootstrap.Modal) {
            var bsModal = bootstrap.Modal.getInstance(comboModal);
            if (bsModal) bsModal.hide();
        }
        comboModal.style.display = 'none';
        comboModal.classList.remove('show');
    }

    var closeBtn = document.getElementById('comboModalCloseBtn');
    if (closeBtn) closeBtn.addEventListener('click', hideComboModal);
    var cancelBtn = document.getElementById('comboModalCancelBtn');
    if (cancelBtn) cancelBtn.addEventListener('click', hideComboModal);

    var confirmComboBtn = document.getElementById('comboModalConfirmBtn');
    if (confirmComboBtn) {
        confirmComboBtn.addEventListener('click', function() {
            if (!currentComboProdId) return;
            var meta = combosData[currentComboProdId];
            if (!meta) return;

            var selectedChoices = [];
            var allChosen = true;

            meta.groups.forEach(function(group) {
                var checked = document.querySelector('input[name="combo_group_' + group.id + '"]:checked');
                if (checked) {
                    selectedChoices.push({
                        group_id: group.id,
                        group_name: checked.getAttribute('data-group-name'),
                        combo_item_id: parseInt(checked.value),
                        product_id: parseInt(checked.getAttribute('data-prod-id')),
                        name: checked.getAttribute('data-name'),
                        extra_price: parseFloat(checked.getAttribute('data-extra-price')) || 0
                    });
                } else {
                    allChosen = false;
                }
            });

            if (!allChosen) {
                alert('Please select one item from each combo section.');
                return;
            }

            var hiddenInp = document.getElementById('food_combo_data_' + currentComboProdId);
            if (hiddenInp) hiddenInp.value = JSON.stringify(selectedChoices);

            var qtyInp = document.getElementById('food_qty_' + currentComboProdId);
            if (qtyInp && (parseInt(qtyInp.value) || 0) === 0) {
                qtyInp.value = 1;
            }

            var summaryText = selectedChoices.map(function(c) { return c.name; }).join(' + ');
            var previewEl = document.getElementById('combo_subtext_' + currentComboProdId);
            if (previewEl) {
                previewEl.textContent = '✓ ' + summaryText;
                previewEl.classList.remove('d-none');
            }

            var editLink = document.querySelector('.combo-customize-btn[data-prod-id="' + currentComboProdId + '"]');
            if (editLink) editLink.classList.remove('d-none');

            hideComboModal();
            updatePreorderTotal();
        });
    }

    function updatePreorderTotal() {
        var total = 0;
        var itemsCount = 0;
        var dishesCount = 0;

        document.querySelectorAll('.preorder-qty-input').forEach(function(inp) {
            var qty = parseFloat(inp.value) || 0;
            var price = parseFloat(inp.getAttribute('data-price')) || 0;
            var prodId = inp.id.replace('food_qty_', '');
            var card = document.getElementById('dish_card_' + prodId);
            var badge = card ? card.querySelector('.dish-selected-badge') : null;
            var comboSub = document.getElementById('combo_subtext_' + prodId);
            var comboEdit = document.querySelector('.combo-customize-btn[data-prod-id="' + prodId + '"]');
            var comboHidden = document.getElementById('food_combo_data_' + prodId);

            if (qty > 0) {
                var comboExtra = 0;
                if (comboHidden && comboHidden.value) {
                    try {
                        var cChoices = JSON.parse(comboHidden.value);
                        if (Array.isArray(cChoices)) {
                            cChoices.forEach(function(cc) {
                                comboExtra += (parseFloat(cc.extra_price) || 0);
                            });
                        }
                    } catch(e) {}
                }
                total += qty * (price + comboExtra);
                itemsCount += qty;
                dishesCount += 1;
                if (card) {
                    card.style.borderColor = '#16a34a';
                    card.style.backgroundColor = '#f0fdf4';
                    card.style.boxShadow = '0 3px 8px rgba(22, 163, 74, 0.12)';
                }
                if (badge) {
                    badge.classList.remove('d-none');
                }
                if (comboSub && comboHidden && comboHidden.value) {
                    comboSub.classList.remove('d-none');
                }
                if (comboEdit && comboHidden && comboHidden.value) {
                    comboEdit.classList.remove('d-none');
                }
            } else {
                if (card) {
                    card.style.borderColor = '#e9ecef';
                    card.style.backgroundColor = '#ffffff';
                    card.style.boxShadow = 'none';
                }
                if (badge) {
                    badge.classList.remove('d-none');
                    badge.classList.add('d-none');
                }
                if (comboSub) comboSub.classList.add('d-none');
                if (comboEdit) comboEdit.classList.add('d-none');
                if (comboHidden) comboHidden.value = '';
            }
        });

        var totalFormatted = currSymbol + ' ' + total.toFixed(2);
        var disp = document.getElementById('preorder_total_display');
        if (disp) disp.textContent = totalFormatted;

        var countBadge = document.getElementById('preorder_items_count_badge');
        if (countBadge) {
            countBadge.textContent = itemsCount + ' item' + (itemsCount === 1 ? '' : 's') + ' selected';
        }

        var summaryBar = document.getElementById('preorder_summary_bar');
        var summaryDishes = document.getElementById('summary_dishes_text');
        var summaryTotal = document.getElementById('summary_total_text');

        if (summaryBar) {
            if (itemsCount > 0) {
                summaryBar.classList.remove('d-none');
                if (summaryDishes) summaryDishes.textContent = itemsCount + ' item' + (itemsCount === 1 ? '' : 's') + ' (' + dishesCount + ' dishes)';
                if (summaryTotal) summaryTotal.textContent = totalFormatted;
            } else {
                summaryBar.classList.add('d-none');
            }
        }

        var submitBtn = document.querySelector('form button[type="submit"]');
        if (submitBtn) {
            if (itemsCount > 0) {
                submitBtn.innerHTML = 'Proceed to Online Payment (' + totalFormatted + ') →';
            } else {
                submitBtn.innerHTML = 'Confirm Appointment';
            }
        }

        // Update collapsed header badge if items are pre-ordered
        var collapsedBadge = document.getElementById('preorder_collapsed_badge');
        var collapsedCount = document.getElementById('collapsed_items_count');
        var collapsedPrice = document.getElementById('collapsed_total_price');
        if (collapsedBadge) {
            if (itemsCount > 0) {
                collapsedBadge.classList.remove('d-none');
                if (collapsedCount) collapsedCount.textContent = itemsCount + ' item' + (itemsCount === 1 ? '' : 's');
                if (collapsedPrice) collapsedPrice.textContent = totalFormatted;
            } else {
                collapsedBadge.classList.add('d-none');
            }
        }
    }

    // Toggle Food Menu Open / Closed
    var toggleBtn = document.getElementById('btn_toggle_food_menu');
    var foodBody = document.getElementById('preorder_food_body');
    var toggleText = document.getElementById('toggle_food_btn_text');
    var toggleIcon = document.getElementById('toggle_food_icon');

    if (toggleBtn && foodBody) {
        toggleBtn.addEventListener('click', function() {
            var isHidden = foodBody.classList.contains('d-none');
            if (isHidden) {
                foodBody.classList.remove('d-none');
                if (toggleText) toggleText.textContent = '✕ Close Food Menu';
                if (toggleIcon) toggleIcon.textContent = '▲';
                toggleBtn.style.background = '#e2e8f0';
                toggleBtn.style.color = '#1e293b';
                toggleBtn.style.border = '1px solid #cbd5e1';
                foodBody.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            } else {
                foodBody.classList.add('d-none');
                if (toggleText) toggleText.textContent = '🍽️ Pre-Order Food';
                if (toggleIcon) toggleIcon.textContent = '▼';
                toggleBtn.style.background = '#f59e0b';
                toggleBtn.style.color = '#ffffff';
                toggleBtn.style.border = 'none';
            }
        });
    }

    // Stepper + buttons
    document.querySelectorAll('.preorder-btn-plus').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            var id = this.getAttribute('data-prod-id');
            var itemRow = this.closest('.food-dish-item');
            var isCombo = itemRow && (itemRow.getAttribute('data-is-combo') === 'true');
            var inp = document.getElementById('food_qty_' + id);
            if (!inp) return;

            if (isCombo) {
                var currentVal = parseInt(inp.value) || 0;
                var comboHidden = document.getElementById('food_combo_data_' + id);
                if (currentVal === 0 || !comboHidden || !comboHidden.value) {
                    showComboModal(id);
                } else {
                    inp.value = currentVal + 1;
                    updatePreorderTotal();
                }
            } else {
                inp.value = (parseInt(inp.value) || 0) + 1;
                updatePreorderTotal();
            }
        });
    });

    // Combo customize edit links
    document.querySelectorAll('.combo-customize-btn').forEach(function(link) {
        link.addEventListener('click', function() {
            var id = this.getAttribute('data-prod-id');
            showComboModal(id);
        });
    });

    // Stepper - buttons
    document.querySelectorAll('.preorder-btn-minus').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            var id = this.getAttribute('data-prod-id');
            var inp = document.getElementById('food_qty_' + id);
            if (inp) {
                inp.value = Math.max(0, (parseInt(inp.value) || 0) - 1);
                updatePreorderTotal();
            }
        });
    });

    // Input typing
    document.querySelectorAll('.preorder-qty-input').forEach(function(inp) {
        inp.addEventListener('input', updatePreorderTotal);
    });

    // Clear all
    var clearBtn = document.getElementById('btn_clear_preorder');
    if (clearBtn) {
        clearBtn.addEventListener('click', function() {
            document.querySelectorAll('.preorder-qty-input').forEach(function(inp) {
                inp.value = 0;
            });
            document.querySelectorAll('input[id^="food_combo_data_"]').forEach(function(cInp) {
                cInp.value = '';
            });
            updatePreorderTotal();
        });
    }

    // Category filter & Search
    var activeCat = 'all';
    var searchVal = '';

    function filterDishes() {
        var items = document.querySelectorAll('.food-dish-item');
        items.forEach(function(item) {
            var catIds = (item.getAttribute('data-categories') || '').split(',');
            var name = item.getAttribute('data-name') || '';

            var matchCat = (activeCat === 'all') || catIds.includes(activeCat);
            var matchSearch = !searchVal || name.includes(searchVal);

            if (matchCat && matchSearch) {
                item.style.display = '';
            } else {
                item.style.display = 'none';
            }
        });
    }

    document.querySelectorAll('.category-pill').forEach(function(pill) {
        pill.addEventListener('click', function() {
            document.querySelectorAll('.category-pill').forEach(function(p) {
                p.style.backgroundColor = '#f8fafc';
                p.style.color = '#475569';
                p.style.borderColor = '#e2e8f0';
                p.style.boxShadow = 'none';
                p.classList.remove('active-cat-btn');
            });
            this.classList.add('active-cat-btn');
            this.style.backgroundColor = '#1e293b';
            this.style.color = '#ffffff';
            this.style.borderColor = '#1e293b';
            this.style.boxShadow = '0 2px 4px rgba(30,41,59,0.2)';

            activeCat = this.getAttribute('data-cat-id');
            filterDishes();
        });
    });

    var searchInput = document.getElementById('preorder_search_input');
    if (searchInput) {
        searchInput.addEventListener('input', function() {
            searchVal = this.value.trim().toLowerCase();
            filterDishes();
        });
    }

    // Initial calculation on load
    updatePreorderTotal();
});
//
